import utils

def word_count(text: str) -> dict[str, int]:
    """
    Returns a mapping from each whitespace-separated word (lowercased, 
    with punctuation stripped from both ends) to the number of times it appears.
    """
    if not text:
        return {}

    # Split text by whitespace
    raw_words = text.split()

    counts = {}

    for raw in raw_words:
        # Strip punctuation from both ends using regex
        # Matches non-alphanumeric characters at start (^) or end ($)
        cleaned = re.sub(r'^[^a-zA-Z0-9]+|[^a-zA-Z0-9]+$', '', raw)

        if not cleaned:
            continue

        word = cleaned.lower()

        if word in counts:
            counts[word] += 1
        else:
            counts[word] = 1

